"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8848],{78848:e=>{e.exports=JSON.parse('{"slug":"deficit-byudzheta-2026-7-trln-zaimy","locale":"zh","title":"财政部：2026年预算赤字将达7.3万亿卢布，接近计划的2倍","description":"财政部估计2026年赤字7.3万亿卢布，占GDP的3.2%。分析缺口来源、政府借款，以及对存贷款的影响。","blocks":[{"id":"b001","kind":"paragraph","text":"财政部估计2026年联邦预算赤字7.3万亿卢布，占GDP的3.2%；法定计划为3.8万亿、1.6%GDP，2025年实际5.7万亿。2026年支出将超计划4.5万亿，达到48.6万亿。收入约多1万亿：非油气收入多2.3万亿，油气少1.3万亿至7.6万亿。净差额3.5万亿加到原计划3.8万亿之上。"},{"id":"b002","kind":"paragraph","text":"财政部未细列哪些支出增加，自2022年起国防执行数据保密。预算文件中的2026年国防支出为12.1万亿卢布，2027年17.1万亿。非官方估计本年末约17万亿；若属实，国防超支约5万亿，超过整体预算超支，意味着其他项目反而低于计划。2026年一月至七月支出同比增14.5%，收入增8.8%，财政部当时解释为合同预付款。"},{"id":"b003","kind":"paragraph","text":"大部分缺口靠举债：净借款从原方案4.2万亿升至5万亿卢布，另从国家福利基金提取459十亿。合计约5.5万亿，覆盖7.3万亿中的大部，其余来源未在材料中说明。第四季度计划发行联邦债券OFZ共2.45万亿，比第二、第三季度计划高63%。年末国债将升至46.1万亿卢布，占GDP的19.9%。"},{"id":"b004","kind":"paragraph","text":"一座只有一家银行的城市突然出现巨额借款人。银行资金没有增加，只好提高利率，所有人的贷款都变贵。债市中的这个借款人就是国家，形成“挤出效应”：政府借走本可供企业和家庭使用的资金，抬高其价格。2026年九月23日，财政部出售12年期OFZ，年收益率16.44%，而央行关键利率14%。投资者要求的收益率也反映对通胀和利率长期偏高的预期。"},{"id":"b005","kind":"paragraph","text":"普通人通过利率受到影响。政府大量高成本借款时，银行买OFZ有吸引力，也愿为存款支付更高利息；贷款同理降价更慢。超收入支出增加需求并推升物价，央行决定利率时会考虑预算。下次决定在十月23日。"},{"id":"b006","kind":"paragraph","text":"长期存款能锁定当前利率，但若通胀加速，部分收益会被物价吞噬。短存款保留流动性，却在降息时迅速被银行下调报价。当前贷款很贵；等待便宜贷款也有风险，预算每季借2.45万亿卢布时，没人能承诺利率下降。"},{"id":"b007","kind":"heading","text":"俄罗斯2026年预算赤字是多少？"},{"id":"b008","kind":"paragraph","text":"财政部估计7.3万亿卢布，占GDP的3.2%。预算法律原定3.8万亿、1.6%GDP；2025年为5.7万亿。"},{"id":"b009","kind":"heading","text":"政府如何填补预算赤字？"},{"id":"b010","kind":"paragraph","text":"主要靠借款。2026年通过联邦债券的净借款将增至5万亿卢布，第四季度计划发行2.45万亿；另从国家福利基金提取459十亿。"},{"id":"b011","kind":"heading","text":"赤字如何影响存贷款利率？"},{"id":"b012","kind":"paragraph","text":"国家大量借款会使其他人融资成本上升。2026年九月23日，财政部发行12年期OFZ，收益率16.44%，关键利率14%。银行能以这种收益购买国债时，存款利息维持吸引力，贷款降价则慢。"}],"sources":[{"label":"财政部将26年赤字预测上调至GDP的3.2%，动用福利基金并扩大借款","url":"https://ru.themoscowtimes.com/2026/09/29/eksklyuziv-minfin-povysil-otsenku-defitsita-byudzheta-rf-v-26g-do-32-vvp-potratit-chast-fnb-i-narastit-zaymy-a207226"},{"label":"俄罗斯预算赤字增至6.455万亿卢布","url":"https://www.profinance.ru/news2/2026/08/11/cjyj-defitsit-rossijskogo-byudzheta-vyros-do-6455-trilliona-rublej.html"},{"label":"俄罗斯将27年军费较计划提高27%","url":"https://ru.themoscowtimes.com/2026/09/28/eksklyuziv-rf-uvelichit-voennye-raskhody-v-27g-na-27-ot-plana-a207209"},{"label":"俄罗斯本年军费将接近17万亿，比计划高40%","url":"https://thebell.io/voennye-raskhody-rossii-v-etom-godu-vyrastut-pochti-do-17-trln-rubley-na-40-bolshe-plana"},{"label":"财政部计划第四季度发行2.45万亿卢布OFZ","url":"https://www.interfax.ru/russia/1119745"},{"label":"财政部发行OFZ PD-26253共15.3十亿卢布，收益率16.44%","url":"https://ru.themoscowtimes.com/2026/09/23/minfin-rf-razmestil-ofz-pd-26253-na-153-mlrd-r-pod-1644-pri-sprose-665-mlrd-r-a206786"},{"label":"俄罗斯央行维持关键利率14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"0318e1238e0b1b917560ee37a35c2d4c75abd5d23ee16e401de880eeb401e7a6"}')}}]);